function makeStorage() {
  let highest = 0;
  let data = null;
  return function write(token, value) {
    if (token < highest) {
      console.log(`REJECT token=${token} (highest=${highest}) value=${value}`);
      return false;
    }
    highest = token;
    data = value;
    console.log(`ACCEPT token=${token} value=${value}`);
    return true;
  };
}

const write = makeStorage();
// Old leader A writes before its GC pause
write(33, 'A:v1-start');
// A pauses; coordinator elects B; B writes
write(34, 'B:v2');
// A wakes from the pause and finishes its stale write
write(33, 'A:v1-finish');
